/* ==========================================================================
   RRRT SLIP HEADER BANNER  (loaded by index.html before the main script)
   data  = the banner picture as base64 text (JPEG). Replace the text to change the banner.
   ratio = picture height / picture width (used to reserve the right space on the slip).
   If this file is missing, RRRT slips print with a plain text heading instead.
   ========================================================================== */
window.RRRT_HEADER = {
  ratio: 0.1045,
  data: "data:image/jpeg;base64,"
};
